class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        word = [None] * L
        fixed = [False] * L

        # Apply constraints forced by 'T' positions.
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        word[pos] = str2[j]
                        fixed[pos] = True
                    elif word[pos] != str2[j]:
                        return ""

        # Fill free positions with 'a' (smallest letter).
        for p in range(L):
            if word[p] is None:
                word[p] = 'a'

        target = list(str2)

        # Break every 'F' window that currently equals str2.
        # Change the last free position in the window to 'b'.
        for i in range(n):
            if str1[i] == 'F' and word[i:i + m] == target:
                p = -1
                for q in range(i + m - 1, i - 1, -1):
                    if not fixed[q]:
                        p = q
                        break
                if p == -1:
                    return ""
                word[p] = 'b'

        # Final verification of all 'F' constraints.
        for i in range(n):
            if str1[i] == 'F' and word[i:i + m] == target:
                return ""

        return ''.join(word)

