from collections import defaultdict

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N):
            # Count beautiful numbers in [1, N]
            if N <= 0:
                return 0
            digits = [int(ch) for ch in str(N)]
            # free: numbers already strictly less than prefix of N
            # key = (digit_sum, digit_product, started)
            free = defaultdict(int)
            # tight state: the prefix of N itself
            t_sum, t_prod, t_started = 0, 1, False

            for d in digits:
                new_free = defaultdict(int)
                for (s, p, st), c in free.items():
                    for x in range(10):
                        if not st and x == 0:
                            new_free[(0, 1, False)] += c
                        else:
                            new_free[(s + x, p * x, True)] += c
                # branch off from tight prefix with a smaller digit
                for x in range(d):
                    if not t_started and x == 0:
                        new_free[(0, 1, False)] += 1
                    else:
                        new_free[(t_sum + x, t_prod * x, True)] += 1
                # advance tight prefix
                if not t_started and d == 0:
                    pass
                else:
                    t_sum, t_prod, t_started = t_sum + d, t_prod * d, True
                free = new_free

            total = 0
            for (s, p, st), c in free.items():
                if st and s > 0 and p % s == 0:
                    total += c
            # include N itself
            if t_started and t_sum > 0 and t_prod % t_sum == 0:
                total += 1
            return total

        return count(r) - count(l - 1)

