from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # Alternating sums of a subsequence lie within [-1800, 1800] (at most 150 terms, each <= 12).
        OFF = 1900
        if k > 1800 or k < -1800:
            return -1

        # dp maps (product, parity) -> bitmask over (alternating sum + OFF).
        # parity = number of chosen elements mod 2; parity 0 means the next element is added,
        # parity 1 means it is subtracted. Only non-empty subsequences are stored in dp.
        dp = {}

        for x in nums:
            new = dict(dp)

            def add(key, mask):
                if mask:
                    new[key] = new.get(key, 0) | mask

            # Start a new subsequence with x (it is at index 0, so it is added).
            if x <= limit:
                add((x, 1), 1 << (OFF + x))

            # Extend existing non-empty subsequences with x.
            for (p, par), m in dp.items():
                np_ = p * x
                if np_ > limit:
                    continue
                if par == 0:
                    # x is added: sum increases by x, next parity becomes 1.
                    add((np_, 1), m << x)
                else:
                    # x is subtracted: sum decreases by x, next parity becomes 0.
                    add((np_, 0), m >> x)

            dp = new

        target_bit = OFF + k
        best = -1
        for (p, par), m in dp.items():
            if p <= limit and (m >> target_bit) & 1:
                if p > best:
                    best = p
        return best
